[ApiController]
[Route("api/[controller]")]
[ResponseCache(Duration = 60, Location = ResponseCacheLocation.Any, VaryByQueryKeys = new[] { "category" })]
public class ProductsController : ControllerBase
{
    [HttpGet]
    public async Task<ActionResult<List<ProductDto>>> GetAll()
    {
        // This result is cached for 60 seconds
        var products = await _service.GetAllAsync();
        return Ok(products);
    }
}

using Microsoft.AspNetCore.OutputCaching;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddOutputCache(options =>
{
    // Add a named policy for product listings
    options.AddPolicy("ProductList", policy =>
    {
        policy.Expire(TimeSpan.FromMinutes(2))
              .VaryByQuery("category", "page");
    });
});

var app = builder.Build();

app.UseOutputCache();

app.MapGet("/api/products", async (IProductService service) =>
{
    var products = await service.GetAllAsync();
    return Results.Ok(products);
})
.CacheOutput("ProductList"); // Apply the named policy

app.Run();

